// Sanitize and prepare extracted text + metadata
const rawText = $input.first().json.text || $input.first().json.data || '';
const body = $('Webhook — Receive Resume Upload').first().json.body || {};

const jobTitle = body.job_title || 'General / Not Specified';
const jobDescription = body.job_description || 'No job description provided. Optimize for general ATS systems.';

// Basic cleaning
const cleanedText = rawText
  .replace(/[\r\n]{3,}/g, '\n\n')
  .replace(/\t/g, ' ')
  .replace(/ {3,}/g, '  ')
  .trim();

return [{
  json: {
    rawText: cleanedText,
    jobTitle,
    jobDescription,
    charCount: cleanedText.length,
    timestamp: new Date().toISOString()
  }
}];

// Extract the optimized resume text from Gemini response
const aiResponse = $input.first().json;
let optimizedText = '';

if (aiResponse.message && aiResponse.message.content) {
  optimizedText = aiResponse.message.content;
} else if (aiResponse.text) {
  optimizedText = aiResponse.text;
} else if (aiResponse.output) {
  optimizedText = aiResponse.output;
} else if (aiResponse.choices && aiResponse.choices[0]) {
  optimizedText = aiResponse.choices[0].message?.content || aiResponse.choices[0].text || '';
} else {
  // Fallback: try to find any string content
  const vals = Object.values(aiResponse);
  for (const v of vals) {
    if (typeof v === 'string' && v.length > 100) {
      optimizedText = v;
      break;
    }
  }
  if (!optimizedText) {
    optimizedText = JSON.stringify(aiResponse);
  }
}

// ATS Score simulation
const atsChecks = {
  hasContactSection: /CONTACT INFORMATION/i.test(optimizedText),
  hasSummary: /PROFESSIONAL SUMMARY|SUMMARY/i.test(optimizedText),
  hasSkills: /SKILLS/i.test(optimizedText),
  hasExperience: /WORK EXPERIENCE|EXPERIENCE/i.test(optimizedText),
  hasEducation: /EDUCATION/i.test(optimizedText),
  hasActionVerbs: /(managed|led|developed|created|implemented|increased|reduced|achieved|delivered|built|designed|analyzed|coordinated|maintained)/i.test(optimizedText),
  hasQuantifiedResults: /\d+%|\$\d+|\d+ (people|team|projects|clients|users)/i.test(optimizedText),
  noTables: !/<table|\|.*\|/i.test(optimizedText),
  noBulletSymbols: !/[\u2022\u25CF\u25C6\u25AA\u25A0]/g.test(optimizedText),
  standardDates: /\d{4}|jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec/i.test(optimizedText)
};

const passedChecks = Object.values(atsChecks).filter(Boolean).length;
const totalChecks = Object.keys(atsChecks).length;
const atsScore = Math.round((passedChecks / totalChecks) * 100);

return [{
  json: {
    optimizedResume: optimizedText.trim(),
    atsScore,
    atsChecks,
    wordCount: optimizedText.trim().split(/\s+/).length,
    optimizedAt: new Date().toISOString()
  }
}];
